import type { EngineInterface, Register } from 'claude-code'

import { registerBand } from './band'
import { registerEnforcer } from './enforcer'
import { registerGuard } from './guard'
import { registerPane } from './pane'
import {
  EMPTY,
  EVIDENCE_DIR,
  NO_VOYAGE,
  VOYAGE_FILE,
  changedKeys,
  evidenceNames,
  hasStatusFormatter,
  isShipitPath,
  makerModelOf,
  pathUnder,
  resetSeams,
  settle,
  snapshotOf,
  statusText,
} from './state'
import type { Disk, Snapshot } from './state'
import { isOwned, parseProgress, parseVoyage } from './voyage'

// The shipit mod's entry. This file keeps the `$.state` snapshot of the voyage
// this session owns current and applies the `maker_model` option; guard,
// enforcer, band and pane each register from their own file. The mod reads
// `.shipit/`; it never writes there.

const VOYAGE = { plugin: 'shipit', key: 'voyage' } as const
const PROGRESS = { plugin: 'shipit', key: 'progress' } as const
const EVIDENCE = { plugin: 'shipit', key: 'evidence' } as const
const PAUSED = { plugin: 'shipit', key: 'paused' } as const
const NUDGES = { plugin: 'shipit', key: 'nudges' } as const

/**
 * The mod's state as it stands; never throws. Every `$.state.get` of one
 * dispatch reads one moment, so a value this dispatch wrote is not seen here.
 */
const readSnapshot = async ($: EngineInterface): Promise<Snapshot> => {
  try {
    return snapshotOf({
      voyage: (await $.state.get(VOYAGE)).value,
      progress: (await $.state.get(PROGRESS)).value,
      evidence: (await $.state.get(EVIDENCE)).value,
      paused: (await $.state.get(PAUSED)).value,
      nudges: (await $.state.get(NUDGES)).value,
    })
  } catch {
    return EMPTY
  }
}

/** What `.shipit/voyage.json`, the plan it names and the evidence folder say now; never throws. */
const readDisk = async ($: EngineInterface): Promise<Disk> => {
  try {
    const given = await $.session.root()
    const root = (await $.fs.stat(given, { resolve: true }).catch(() => undefined))?.realPath ?? given
    const voyage = parseVoyage(await $.fs.read(pathUnder(root, VOYAGE_FILE)).catch(() => undefined))
    if (voyage === undefined || !isOwned(voyage, await $.session.id())) return NO_VOYAGE

    // An unreadable plan is progress unknown (null), never zero.
    const plan = await $.fs.read(pathUnder(root, voyage.activePlan)).catch(() => undefined)
    const entries = await $.fs.list(pathUnder(root, EVIDENCE_DIR)).catch(() => [])
    return { voyage, progress: parseProgress(plan) ?? null, evidence: evidenceNames(entries) }
  } catch {
    return NO_VOYAGE
  }
}

/**
 * Reads the disk again and writes what changed to `$.state`: the one writer of
 * `voyage`, `progress` and `evidence`. Never throws, and is never called while
 * a `ui.render` hook draws. `voyage` is written last, so a reader it wakes
 * finds the rest current.
 */
const refresh = async ($: EngineInterface): Promise<Snapshot> => {
  try {
    const before = await readSnapshot($)
    const now = settle(before, await readDisk($))
    for (const key of changedKeys(before, now)) {
      if (key === 'progress') await $.state.set(PROGRESS, now.progress)
      else if (key === 'evidence') await $.state.set(EVIDENCE, now.evidence)
      else if (key === 'paused') await $.state.set(PAUSED, now.paused)
      else if (key === 'nudges') await $.state.set(NUDGES, now.nudges)
      else await $.state.set(VOYAGE, now.voyage)
    }
    if (hasStatusFormatter()) $.ui.status(statusText(now))
    return now
  } catch {
    return EMPTY
  }
}

export const register: Register = (on, options) => {
  resetSeams()

  on('session.start', async ($, e, next) => {
    await refresh($)
    return next(e)
  })

  // A shipit skill is about to run: it may be starting, resuming or taking
  // over a voyage. Literals (state.ts SKILLS), so `claude plugin validate` lists them.
  on('skill.prompt', { skill: ['shipit:go', 'shipit:plan', 'shipit:execute', 'shipit:review'] }, async ($, e, next) => {
    await refresh($)
    return next(e)
  })

  // The guard registers BEFORE the observer below. Both hook `tool.call` for
  // Write and Edit, and when one plugin has two hooks on an event, a failure
  // in either (a throw, a timeout, a re-entry) is answered by the `.catch` of
  // the one registered first. That must be the guard's deny, never the
  // observer's pass-through, or an armed guard would fail open.
  registerGuard(on, options)

  // An observer, never a gate: the main loop wrote under `.shipit/` (the
  // voyage record, a plan checkbox), so the snapshot is read again once the
  // write has run. The call and its result pass through as they were; a write
  // the guard denied never ran, and nothing is read again for it.
  on('tool.call', { tool: ['Write', 'Edit'] }, async ($, e, next) => {
    const ran = await next(e)
    if (e.agentId === undefined && isShipitPath(e.file_path)) await refresh($)
    return ran
  }).catch(($, e, next) => next(e))

  // What no Write or Edit showed (a voyage.json removed through the shell,
  // evidence a Maker wrote) is picked up as each main-loop turn ends. The
  // refresh comes BEFORE `next`, so enforcer.ts, reading after its own `next`
  // settles, sees it wherever the two hooks stand.
  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) await refresh($)
    return next(e)
  })

  // The `maker_model` option decides what shipit:maker runs on. A plugin's
  // agent arrives as `<plugin>:<name>` (verified), matched exactly.
  on('agent.spawn', { subagentType: 'shipit:maker' }, ($, e, next) => {
    const model = makerModelOf(options)
    return next(model === undefined ? e : { ...e, model })
  }).catch(($, e, next) => next(e))

  // Enforcer, band, pane: each fills its seams (state.ts) synchronously here.
  registerEnforcer(on, options)
  registerBand(on, options)
  registerPane(on, options)
}

