// The voyage band and the status line entry.
//
// Contract:
// - `ui.render` on `{ component: 'AbovePrompt' }`: `await readSnapshot($)`
//   (the read subscribes the band, so every state write redraws it; no
//   `$.ui.invalidate`). With `snapshot.voyage` non-null and its phase not
//   `done`, draw one row sized to `e.props.bodyColumns`: phase trail, plan
//   name, `done/total` (`progress` may be null: unknown, not 0/0), paused /
//   awaiting-you markers, and one Button per `listBandActions()` entry
//   (`key`, `label`, `onPress: () => $.ui.open(action.open)`; Task 14
//   contributes the pane's). Otherwise `return next(e)`.
// - Status line: call `setStatusFormatter(snapshot => text | undefined)`
//   synchronously in `registerBand` with a PURE function (`shipit: execute
//   3/9`; undefined without an owned voyage or in `done`). register.tsx then
//   calls `$.ui.status(statusText(snapshot))` after every refresh, and the
//   pause writers in enforcer.ts / pane.tsx do after theirs. Do not call
//   `$.ui.status` from the render hook.
// - `$` stays in this file: `claude plugin validate` refuses a `$` handed to
//   an imported function, and a `$.state` reference that is not a const here.
// - From './state': snapshotOf, EMPTY, setStatusFormatter, listBandActions.
//   From './voyage': isActivePhase, isGatePhase and the types.
// - Must NOT: write state while drawing, or draw anything without an owned
//   voyage.

import type { EngineInterface, On, PluginOptions } from 'claude-code'

import { EMPTY, listBandActions, setStatusFormatter, snapshotOf } from './state'
import type { BandAction, Snapshot } from './state'
import { isActivePhase, isGatePhase } from './voyage'
import type { Phase } from './voyage'

// --- provided by Task 10 (state.ts explains why this cannot be imported) ----

const VOYAGE = { plugin: 'shipit', key: 'voyage' } as const
const PROGRESS = { plugin: 'shipit', key: 'progress' } as const
const EVIDENCE = { plugin: 'shipit', key: 'evidence' } as const
const PAUSED = { plugin: 'shipit', key: 'paused' } as const
const NUDGES = { plugin: 'shipit', key: 'nudges' } as const

/**
 * The mod's state as it stands; never throws. Every `$.state.get` of one
 * dispatch reads one moment, so a value this dispatch wrote is not seen here.
 */
const readSnapshot = async ($: EngineInterface): Promise<Snapshot> => {
  try {
    return snapshotOf({
      voyage: (await $.state.get(VOYAGE)).value,
      progress: (await $.state.get(PROGRESS)).value,
      evidence: (await $.state.get(EVIDENCE)).value,
      paused: (await $.state.get(PAUSED)).value,
      nudges: (await $.state.get(NUDGES)).value,
    })
  } catch {
    return EMPTY
  }
}

// --- what the band and the status line say (pure) ---------------------------

export type Stage = 'plan' | 'execute' | 'review'

const STAGES = ['plan', 'execute', 'review'] as const
const STAGE_LABEL: Record<Stage, string> = { plan: 'Plan', execute: 'Execute', review: 'Review' }

export const SEPARATOR = '›'
export const ELLIPSIS = '…'
export const UNKNOWN_COUNT = '?/?'
/** Cells between two parts of the row: the row Box's `gap`. */
export const GAP = 1
/** Cells a Button takes beside its label: the terminal's `[ label ]`, the widest form. */
export const BUTTON_CHROME = 4
/** A plan name is shown in at least this many cells (ellipsis included), or not at all. */
export const MIN_NAME = 4

/** The trail stage a phase belongs to; undefined for `done`. */
export const stageOf = (phase: Phase): Stage | undefined => {
  switch (phase) {
    case 'planning':
    case 'plan_gate':
      return 'plan'
    case 'executing':
      return 'execute'
    case 'reviewing':
    case 'ship_gate':
      return 'review'
    default:
      return undefined
  }
}

/** What there is to say about a snapshot; undefined without an owned voyage or in `done`. */
export type BandFacts = {
  stage: Stage
  planName: string
  /** `done/total`; undefined when progress is unknown (never `0/0` for unknown). */
  count: string | undefined
  isPaused: boolean
  isAwaiting: boolean
}

export const bandFacts = (snapshot: Snapshot): BandFacts | undefined => {
  const { voyage, progress } = snapshot
  if (voyage === null || !isActivePhase(voyage.phase)) return undefined
  const stage = stageOf(voyage.phase)
  if (stage === undefined) return undefined
  return {
    stage,
    planName: voyage.planName,
    count: progress === null ? undefined : `${progress.done}/${progress.total}`,
    isPaused: snapshot.paused,
    isAwaiting: isGatePhase(voyage.phase) || voyage.awaitingUser,
  }
}

/**
 * The status line entry: `shipit: execute 3/9`, with `(paused)`, `(awaiting
 * you)` or both after it; the count is left out when progress is unknown.
 * Undefined (which clears the entry) without an owned voyage or in `done`.
 */
export const formatStatus = (snapshot: Snapshot): string | undefined => {
  const facts = bandFacts(snapshot)
  if (facts === undefined) return undefined
  const markers = [facts.isPaused ? 'paused' : '', facts.isAwaiting ? 'awaiting you' : ''].filter(marker => marker !== '')
  return ['shipit:', facts.stage, facts.count ?? '', markers.length === 0 ? '' : `(${markers.join(', ')})`]
    .filter(word => word !== '')
    .join(' ')
}

// --- the row's layout (pure) ------------------------------------------------

export type Emphasis = 'strong' | 'dim' | 'plain'

/** One cell-run of the row, left to right; `id` says what it is. */
export type BandPart =
  | { kind: 'text'; id: string; text: string; emphasis: Emphasis }
  | { kind: 'button'; id: string; text: string; action: BandAction }

const cells = (text: string): number => [...text].length

export const partWidth = (part: BandPart): number => cells(part.text) + (part.kind === 'button' ? BUTTON_CHROME : 0)

/** Cells the parts take as one row, gaps included. */
export const rowWidth = (parts: readonly BandPart[]): number =>
  parts.reduce((sum, part) => sum + partWidth(part), 0) + Math.max(0, parts.length - 1) * GAP

/** `text` in at most `width` cells, its end replaced by an ellipsis when cut. */
export const truncate = (text: string, width: number): string => {
  const chars = [...text]
  if (chars.length <= width) return text
  if (width <= 0) return ''
  return width === 1 ? ELLIPSIS : `${chars.slice(0, width - 1).join('')}${ELLIPSIS}`
}

type Shape = {
  trail: 'full' | 'current'
  hasName: boolean
  markers: 'long' | 'short' | 'none'
  hasButtons: boolean
  hasCount: boolean
}

// What gives way as the row narrows, first to last: the plan name is cut with
// an ellipsis (down to MIN_NAME cells), the trail collapses to the current
// stage (the name gets its room back), the name goes, the markers shorten,
// the Buttons go, the markers go, the count goes. Under that the stage word
// itself is cut to the width.
const SHAPES: readonly Shape[] = [
  { trail: 'full', hasName: true, markers: 'long', hasButtons: true, hasCount: true },
  { trail: 'current', hasName: true, markers: 'long', hasButtons: true, hasCount: true },
  { trail: 'current', hasName: false, markers: 'long', hasButtons: true, hasCount: true },
  { trail: 'current', hasName: false, markers: 'short', hasButtons: true, hasCount: true },
  { trail: 'current', hasName: false, markers: 'short', hasButtons: false, hasCount: true },
  { trail: 'current', hasName: false, markers: 'none', hasButtons: false, hasCount: true },
  { trail: 'current', hasName: false, markers: 'none', hasButtons: false, hasCount: false },
]

const text = (id: string, value: string, emphasis: Emphasis): BandPart => ({ kind: 'text', id, text: value, emphasis })

const trailParts = (facts: BandFacts, trail: Shape['trail']): BandPart[] =>
  trail === 'current'
    ? [text(`stage-${facts.stage}`, STAGE_LABEL[facts.stage], 'strong')]
    : STAGES.flatMap((stage, index) => [
        ...(index === 0 ? [] : [text(`separator-${index}`, SEPARATOR, 'dim')]),
        text(`stage-${stage}`, STAGE_LABEL[stage], stage === facts.stage ? 'strong' : 'dim'),
      ])

const markerParts = (facts: BandFacts, markers: Shape['markers']): BandPart[] =>
  markers === 'none'
    ? []
    : [
        ...(facts.isPaused ? [text('paused', markers === 'long' ? 'paused' : '||', 'strong')] : []),
        ...(facts.isAwaiting ? [text('awaiting', markers === 'long' ? 'awaiting you' : 'you?', 'strong')] : []),
      ]

const shaped = (facts: BandFacts, shape: Shape, actions: readonly BandAction[], nameWidth: number): BandPart[] => [
  ...trailParts(facts, shape.trail),
  ...(nameWidth > 0 ? [text('name', truncate(facts.planName, nameWidth), 'plain')] : []),
  ...(shape.hasCount ? [text('count', facts.count ?? UNKNOWN_COUNT, 'plain')] : []),
  ...markerParts(facts, shape.markers),
  ...(shape.hasButtons
    ? actions.map((action): BandPart => ({ kind: 'button', id: action.key, text: action.label, action }))
    : []),
]

/**
 * The band's one row for `snapshot` in `columns` cells: its parts left to
 * right, never wider than `columns` (`rowWidth`). Empty when there is nothing
 * to draw: no owned voyage, `done`, or no room at all.
 */
export const layoutBand = (snapshot: Snapshot, columns: number, actions: readonly BandAction[] = []): BandPart[] => {
  const facts = bandFacts(snapshot)
  const room = Number.isFinite(columns) ? Math.floor(columns) : 0
  if (facts === undefined || room < 1) return []
  const nameCells = cells(facts.planName)

  for (const shape of SHAPES) {
    const bare = shaped(facts, shape, actions, 0)
    if (!shape.hasName || nameCells === 0) {
      if (rowWidth(bare) <= room) return bare
      continue
    }
    const nameRoom = Math.min(nameCells, room - rowWidth(bare) - GAP)
    if (nameRoom >= Math.min(nameCells, MIN_NAME)) return shaped(facts, shape, actions, nameRoom)
  }

  return [text(`stage-${facts.stage}`, truncate(STAGE_LABEL[facts.stage], room), 'strong')]
}

// --- the hooks --------------------------------------------------------------

export const registerBand = (on: On, _options: PluginOptions): void => {
  setStatusFormatter(formatStatus)

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)

    // Read at render time: the pane registers its Button after this function ran.
    const parts = layoutBand(await readSnapshot($), e.props.bodyColumns, listBandActions())
    if (parts.length === 0) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="row" flexWrap="nowrap" gap={GAP} overflow="hidden">
        {parts.map(part =>
          part.kind === 'button' ? (
            <Button
              key={part.id}
              label={part.text}
              onPress={() => {
                void $.ui.open(part.action.open)
              }}
            />
          ) : (
            <Text bold={part.emphasis === 'strong'} dimColor={part.emphasis === 'dim'} wrap="truncate-end">
              {part.text}
            </Text>
          ),
        )}
      </Box>
    )
  })
}

