// The continuation enforcer and the `/shipit` command.
//
// Contract (VOYAGE.md sections 6 and 8):
// - `turn.complete`: `const ran = await next(e)` FIRST, then judge, then
//   `return ran`. register.tsx refreshes the snapshot in its own
//   `turn.complete` hook before it calls `next`, so whichever of the two hooks
//   is outermost, the snapshot read after `next` settles is current.
// - Nudge only when: `e.agentId` is absent, `e.reason === 'answer'`,
//   `isEnforcerEnabled(options)`, `snapshot.voyage` is non-null (owned),
//   `isEnforcerPhase(phase)`, `!voyage.awaitingUser`, `!snapshot.paused`,
//   `workRemains(voyage, progress)` and `snapshot.nudges < MAX_NUDGES`. The
//   nudge is `void $.prompt.submit({ text })` (never awaited, never `asUser`)
//   naming `nextTask(progress)` or the `pendingVerdicts(voyage.verdicts)`,
//   then `setNudges($, snapshot.nudges + 1)`. On reaching MAX_NUDGES, toast
//   once that the enforcer stood down.
// - Resetting the count is NOT yours: register.tsx's refresh zeroes `nudges`
//   whenever the phase, done count or a verdict moved, and when the voyage
//   ends; `setPaused($, false)` zeroes it on resume.
// - Register the `COMMAND` (`shipit`) command in `session.start`; answer
//   `command.run` for status (default) | pause | resume | end. pause / resume
//   are `setPaused` below. `end` asks the model through `$.prompt.submit` to
//   close the voyage per VOYAGE.md: the mod deletes nothing. Any other first
//   word: `findSubcommand(word)?.run(rest, snapshot, e)`; when the answer
//   carries `open`, `await $.ui.open(answer.open)`, then return its `text`
//   (Task 14 contributes `pane` this way). List `listSubcommands()` in the
//   usage text.
// - `$` stays in this file: `claude plugin validate` refuses a `$` handed to
//   an imported function, and a `$.state` reference that is not a const here.
// - From './state': snapshotOf, EMPTY, MAX_NUDGES, COMMAND, isEnforcerEnabled,
//   findSubcommand, listSubcommands, hasStatusFormatter, statusText.
//   From './voyage': isEnforcerPhase, workRemains, nextTask, pendingVerdicts.
// - Must NOT: nudge in planning, plan_gate, ship_gate or done, or after
//   `aborted` / `refusal` / `error`; write `voyage`, `progress` or `evidence`
//   state; write or delete anything under `.shipit/`.

import type { CommandRunInput, EngineInterface, On, PluginOptions } from 'claude-code'

import {
  COMMAND,
  EMPTY,
  MAX_NUDGES,
  VOYAGE_FILE,
  findSubcommand,
  hasStatusFormatter,
  isEnforcerEnabled,
  isGuardEnabled,
  listSubcommands,
  snapshotOf,
  statusText,
} from './state'
import type { Snapshot, Subcommand, SubcommandAnswer } from './state'
import { VERDICT_KEYS, isEnforcerPhase, nextTask, pendingVerdicts, readyTasks, workRemains } from './voyage'

// --- provided by Task 10 (state.ts explains why this cannot be imported) ----

const VOYAGE = { plugin: 'shipit', key: 'voyage' } as const
const PROGRESS = { plugin: 'shipit', key: 'progress' } as const
const EVIDENCE = { plugin: 'shipit', key: 'evidence' } as const
const PAUSED = { plugin: 'shipit', key: 'paused' } as const
const NUDGES = { plugin: 'shipit', key: 'nudges' } as const

/**
 * The mod's state as it stands; never throws. Every `$.state.get` of one
 * dispatch reads one moment, so a value this dispatch wrote is not seen here.
 */
const readSnapshot = async ($: EngineInterface): Promise<Snapshot> => {
  try {
    return snapshotOf({
      voyage: (await $.state.get(VOYAGE)).value,
      progress: (await $.state.get(PROGRESS)).value,
      evidence: (await $.state.get(EVIDENCE)).value,
      paused: (await $.state.get(PAUSED)).value,
      nudges: (await $.state.get(NUDGES)).value,
    })
  } catch {
    return EMPTY
  }
}

/**
 * `/shipit pause` and `/shipit resume`: writes the flag, zeroes the nudge
 * count on resume (VOYAGE.md section 6), brings the status line up to date and
 * answers the snapshot as it now stands.
 */
const setPaused = async ($: EngineInterface, paused: boolean): Promise<Snapshot> => {
  const before = await readSnapshot($)
  await $.state.set(PAUSED, paused)
  if (!paused) await $.state.set(NUDGES, 0)
  const now: Snapshot = { ...before, paused, nudges: paused ? before.nudges : 0 }
  if (hasStatusFormatter()) $.ui.status(statusText(now))
  return now
}

/** Sets the nudge count: a whole number, zero or more. */
const setNudges = async ($: EngineInterface, nudges: number): Promise<void> => {
  await $.state.set(NUDGES, Math.max(0, Math.trunc(nudges)))
}

// --- the enforcer (pure) ------------------------------------------------------

/** What of a `turn.complete` input the enforcer judges by. */
export type TurnEnd = { reason: string; agentId?: string | undefined; isAborted?: boolean | undefined }

/**
 * VOYAGE.md section 8, plus the bound: a main-loop turn that ended on an
 * answer, the enforcer on, an owned voyage in `executing` or `reviewing` that
 * is neither waiting for the user nor paused, work left, and fewer than
 * MAX_NUDGES nudges since anything last moved.
 */
export const shouldNudge = (turn: TurnEnd, isEnabled: boolean, snapshot: Snapshot): boolean => {
  const { voyage, progress, paused, nudges } = snapshot
  return (
    turn.agentId === undefined &&
    turn.reason === 'answer' &&
    turn.isAborted !== true &&
    isEnabled &&
    voyage !== null &&
    isEnforcerPhase(voyage.phase) &&
    !voyage.awaitingUser &&
    !paused &&
    workRemains(voyage, progress) &&
    nudges < MAX_NUDGES
  )
}

const WAY_OUT = `If you are genuinely blocked on the user, set "awaiting_user": true in ${VOYAGE_FILE} and ask them; otherwise keep going without asking.`

/** The continue message for a snapshot `shouldNudge` passed; `count` is this nudge's number. */
export const nudgeText = (snapshot: Snapshot, count: number): string => {
  const { voyage, progress } = snapshot
  if (voyage === null) return ''
  const tail = `${WAY_OUT} (Automatic shipit nudge ${count} of ${MAX_NUDGES}.)`

  if (voyage.phase === 'reviewing') {
    const pending = pendingVerdicts(voyage.verdicts).map(key => `${key} (${voyage.verdicts[key] ?? 'not run'})`)
    return `The shipit voyage "${voyage.planName}" is still in review and the turn ended. Verdicts not yet APPROVE: ${pending.join(', ')}. Continue the review per shipit:review: run the dimensions not yet run, fix what a REJECT named and run those again. ${tail}`
  }

  const task = nextTask(progress)
  const counts = progress === null ? '' : ` (${progress.done}/${progress.total} tasks checked)`
  const next = task === undefined ? 'the next unchecked task' : `the next unchecked task: ${task.id}. ${task.title}`
  return `The shipit voyage "${voyage.planName}" is still executing${counts} and the turn ended. Continue with ${next}. ${tail}`
}

export const STAND_DOWN = `shipit: ${MAX_NUDGES} nudges without progress, so the enforcer stood down. /${COMMAND} resume (or any progress) re-arms it.`

// --- the /shipit command (pure) -------------------------------------------------

export const COMMAND_DESCRIPTION = 'Show, pause, resume or end the shipit voyage'
export const COMMAND_HINT = '[status|pause|resume|end]'

/** The first word of a command's arguments, lower case (`status` when there is none), and what follows it. */
export const parseArgs = (args: string): { word: string; rest: string } => {
  const text = args.trim()
  const cut = text.search(/\s/)
  const word = (cut < 0 ? text : text.slice(0, cut)).toLowerCase()
  return { word: word === '' ? 'status' : word, rest: cut < 0 ? '' : text.slice(cut).trim() }
}

const NO_VOYAGE_TEXT = 'No shipit voyage is owned by this session.'

const onOff = (isOn: boolean): string => (isOn ? 'on' : 'off')

/** `/shipit status`: the voyage as the mod last read it. */
export const statusReport = (snapshot: Snapshot, options: PluginOptions): string => {
  const { voyage, progress, paused, nudges } = snapshot
  const switches = `Enforcer: ${onOff(isEnforcerEnabled(options))} · Guard: ${onOff(isGuardEnabled(options))}`
  if (voyage === null) return `${NO_VOYAGE_TEXT} Start one with /shipit:go.\n${switches}`

  const lines = [`Voyage: ${voyage.planName} (${voyage.activePlan})`, `Phase: ${voyage.phase}`]
  if (progress === null) {
    lines.push('Tasks: unknown (the plan could not be read)')
  } else {
    const ready = readyTasks(progress).length
    const task = nextTask(progress)
    const next = task === undefined ? 'none left' : `${task.id}. ${task.title}`
    lines.push(
      `Tasks: ${progress.done}/${progress.total} checked · ${ready} ready · ${progress.total - progress.done - ready} blocked · next: ${next}`,
    )
  }
  if (voyage.phase === 'reviewing' || voyage.phase === 'ship_gate') {
    lines.push(`Verdicts: ${VERDICT_KEYS.map(key => `${key} ${voyage.verdicts[key] ?? 'not run'}`).join(' · ')}`)
  }
  lines.push(
    `Paused: ${paused ? 'yes (guard and enforcer suspended)' : 'no'} · Awaiting user: ${voyage.awaitingUser ? 'yes' : 'no'} · Nudges: ${nudges}/${MAX_NUDGES}${nudges >= MAX_NUDGES ? ' (enforcer stood down)' : ''}`,
    switches,
  )
  return lines.join('\n')
}

/** What `/shipit pause` and `/shipit resume` answer; `wasPaused` is the flag before the command. */
export const pauseText = (snapshot: Snapshot, wasPaused: boolean): string => {
  const name = snapshot.voyage?.planName ?? ''
  if (snapshot.paused) {
    return `${wasPaused ? 'Already paused' : 'Paused'}: the guard and the enforcer are suspended for voyage "${name}". /${COMMAND} resume turns them back on.`
  }
  return `${wasPaused ? 'Resumed' : 'Not paused'}: the guard and the enforcer are active for voyage "${name}" and the nudge count is 0.`
}

/** The prompt `/shipit end` hands the model: the model closes the voyage, the mod deletes nothing. */
export const endPrompt = (snapshot: Snapshot): string => {
  const { voyage, progress } = snapshot
  if (voyage === null) return ''
  const checked = progress === null ? 'how many tasks are checked in it' : `the tasks checked (${progress.done}/${progress.total} when last read)`
  return `The user ran /${COMMAND} end. Close the shipit voyage "${voyage.planName}" now, as VOYAGE.md's abandon transition says: remove ${VOYAGE_FILE} and nothing else (the plan, evidence and notepads stay), then report the plan path (${voyage.activePlan}) and ${checked}. Start no further tasks.`
}

/** How long after `/shipit end` answers its request reaches the model, in milliseconds. */
export const END_DELAY_MS = 50

export const END_FAILED = `shipit: the request to end the voyage could not be sent. Ask Claude to remove ${VOYAGE_FILE}.`

/** A contributed subcommand's answer (state.ts `addSubcommand`), or undefined when nothing answers to `word`. */
export const runSubcommand = (
  word: string,
  rest: string,
  snapshot: Snapshot,
  e: CommandRunInput,
): SubcommandAnswer | undefined => findSubcommand(word)?.run(rest, snapshot, e)

export const usageText = (word: string, contributed: readonly Pick<Subcommand, 'name' | 'summary'>[]): string =>
  [
    `Unknown subcommand "${word}". Usage: /${COMMAND} [${['status', 'pause', 'resume', 'end', ...contributed.map(one => one.name)].join('|')}]`,
    '  status  the voyage, its progress and switches (the default)',
    '  pause   suspend the guard and the enforcer',
    '  resume  turn them back on and re-arm the enforcer',
    '  end     ask Claude to close the voyage',
    ...contributed.map(one => `  ${one.name}  ${one.summary}`),
  ].join('\n')

// --- hooks ----------------------------------------------------------------------

export const registerEnforcer = (on: On, options: PluginOptions): void => {
  // The matchers are there because register.tsx hooks both events bare, and a
  // module may hook an event without a matcher only once: every session has a
  // `cwd`, and the enforcer wants the turns that ended on an answer anyway.
  on('session.start', { cwd: /^/ }, async ($, e, next) => {
    // The name is a literal (state.ts COMMAND), so `claude plugin validate` reads
    // the `command.run` hook below as answering this module's own command.
    await $.command
      .register({ name: 'shipit', description: COMMAND_DESCRIPTION, argumentHint: COMMAND_HINT })
      .catch(() => undefined)
    return next(e)
  })

  on('turn.complete', { reason: 'answer' }, async ($, e, next) => {
    const ran = await next(e)
    try {
      const snapshot = await readSnapshot($)
      if (shouldNudge(e, isEnforcerEnabled(options), snapshot)) {
        const count = snapshot.nudges + 1
        await setNudges($, count)
        // Never awaited: it resolves as the nudged turn starts, after this one ends.
        void $.prompt.submit({ text: nudgeText(snapshot, count) }).catch(() => undefined)
        if (count >= MAX_NUDGES) $.ui.toast(STAND_DOWN)
      }
    } catch {
      // The turn's own result stands whatever the enforcer met.
    }
    return ran
  })

  on('command.run', { command: 'shipit' }, async ($, e) => {
    const { word, rest } = parseArgs(e.args)
    const snapshot = await readSnapshot($)

    if (word === 'status') return { text: statusReport(snapshot, options) }

    if (word === 'pause' || word === 'resume') {
      if (snapshot.voyage === null) return { text: `${NO_VOYAGE_TEXT} Nothing to ${word}.` }
      return { text: pauseText(await setPaused($, word === 'pause'), snapshot.paused) }
    }

    if (word === 'end') {
      if (snapshot.voyage === null) return { text: `${NO_VOYAGE_TEXT} Nothing to end.` }
      // `$.prompt.submit` is refused inside a `command.run` hook (its turn
      // would wait on the command this hook is holding), so the request goes
      // out from a timer, once the command has answered.
      const text = endPrompt(snapshot)
      $.clock.after(END_DELAY_MS, () => {
        void $.prompt.submit({ text }).catch(() => $.ui.toast(END_FAILED))
      })
      return { text: `Asking Claude to close voyage "${snapshot.voyage.planName}" (it removes ${VOYAGE_FILE}; the plan stays).` }
    }

    const answer = runSubcommand(word, rest, snapshot, e)
    if (answer === undefined) return { text: usageText(word, listSubcommands()) }
    const { open, ...result } = answer
    if (open !== undefined) await $.ui.open(open)
    return result
  })
}

