// The write-guard: while this session owns a voyage in an active phase and is
// not paused, the main loop may write only inside the project's `.shipit/`
// (and, while planning, the glossary and ADR files). Source changes go through
// a `shipit:maker` subagent, which is never guarded.
//
// Contract (VOYAGE.md section 7):
// - Hook `tool.call` for Write, Edit, NotebookEdit (this build has no
//   MultiEdit), registered with
//   `.catch(($, e, next) => next.called ? next(e) : { deny })`.
// - Pass through (`next(e)`) when `e.agentId` is set, `!isGuardEnabled(options)`,
//   or `readSnapshot($)` is paused, has no `voyage`, or its phase is not
//   `isActivePhase`. `snapshot.voyage` is non-null only for a voyage this
//   session owns, so ownership needs no further check.
// - Otherwise allow only real paths under the resolved project root's
//   `.shipit/` (`$.fs.stat(path, { resolve: true }).realPath`, the root
//   resolved the same way; a path that does not exist yet through its nearest
//   existing ancestor, as plugins/zap/hooks/register.ts does), plus the
//   glossary / ADR paths while `isPlanningPhase(phase)`; deny the rest with a
//   message naming the phase, the path and the remedy (`shipit:maker`, or
//   `/shipit pause`).
// - `$` stays in this file: `claude plugin validate` refuses a `$` handed to
//   an imported function, and a `$.state` reference that is not a const here.
// - From './state': snapshotOf, EMPTY, isGuardEnabled, SHIPIT_DIR, COMMAND,
//   MAKER_AGENT. From './voyage': isActivePhase, isPlanningPhase.
// - Must NOT: write state, re-read voyage.json itself (register.tsx keeps the
//   snapshot current after `.shipit/` writes and at each turn's end),
//   intercept Bash, match paths by substring, or write under `.shipit/`.

import type { EngineInterface, On, PluginOptions } from 'claude-code'

import { COMMAND, EMPTY, MAKER_AGENT, SHIPIT_DIR, isGuardEnabled, snapshotOf } from './state'
import type { Snapshot } from './state'
import { isActivePhase, isPlanningPhase } from './voyage'
import type { Phase } from './voyage'

// --- provided by Task 10 (state.ts explains why this cannot be imported) ----

const VOYAGE = { plugin: 'shipit', key: 'voyage' } as const
const PROGRESS = { plugin: 'shipit', key: 'progress' } as const
const EVIDENCE = { plugin: 'shipit', key: 'evidence' } as const
const PAUSED = { plugin: 'shipit', key: 'paused' } as const
const NUDGES = { plugin: 'shipit', key: 'nudges' } as const

/**
 * The mod's state as it stands; never throws. Every `$.state.get` of one
 * dispatch reads one moment, so a value this dispatch wrote is not seen here.
 */
const readSnapshot = async ($: EngineInterface): Promise<Snapshot> => {
  try {
    return snapshotOf({
      voyage: (await $.state.get(VOYAGE)).value,
      progress: (await $.state.get(PROGRESS)).value,
      evidence: (await $.state.get(EVIDENCE)).value,
      paused: (await $.state.get(PAUSED)).value,
      nudges: (await $.state.get(NUDGES)).value,
    })
  } catch {
    return EMPTY
  }
}

// --- Task 11 ----------------------------------------------------------------

const GLOSSARY = 'CONTEXT.md'
const CONTEXT_MAP = 'CONTEXT-MAP.md'
const ADR_PARENT = 'docs'
const ADR_DIR = 'adr'
const MAX_DEPTH = 256

const remedy = `Delegate the change to a ${MAKER_AGENT} subagent, or run /${COMMAND} pause to suspend the guard.`

const allowedIn = (phase: Phase): string =>
  isPlanningPhase(phase)
    ? `${SHIPIT_DIR}/, ${GLOSSARY} files, ${CONTEXT_MAP} and ${ADR_PARENT}/${ADR_DIR}/`
    : `${SHIPIT_DIR}/`

const refusal = (path: string, phase: Phase, why: string): string =>
  `shipit: ${path} was not written (${why}). The voyage is in phase "${phase}", ` +
  `where the main loop may write only ${allowedIn(phase)} under the project root. ${remedy}`

const separatorOf = (root: string): '/' | '\\' => (root.includes('/') ? '/' : '\\')

const segmentsOf = (path: string, sep: string): string[] => path.split(sep === '\\' ? /[\\/]/ : /\//)

const lastCut = (path: string, sep: string): number =>
  sep === '\\' ? Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\')) : path.lastIndexOf('/')

const trimEnd = (path: string, sep: string): string => path.replace(sep === '\\' ? /[\\/]+$/ : /\/+$/, '')

const isAbsolute = (path: string): boolean => /^([\\/]|[A-Za-z]:[\\/])/.test(path)

const realOf = async ($: EngineInterface, path: string) => $.fs.stat(path, { resolve: true }).catch(() => undefined)

/**
 * Where `path` lands once every symbolic link is followed, or undefined when
 * that cannot be said: the path itself if it exists, else its nearest existing
 * ancestor with the missing names appended. Never placed: a relative path, a
 * `..` segment (the tool and the file system fold it differently around a
 * link), a network or drive-relative spelling, a link that leads nowhere.
 */
const place = async ($: EngineInterface, path: string, sep: string): Promise<string | undefined> => {
  const isPlaceable =
    isAbsolute(path) && !/^[\\/][\\/]/.test(path) && !segmentsOf(path, sep).includes('..')
  if (!isPlaceable) return undefined

  const missing: string[] = []
  let head = path
  for (let depth = 0; depth < MAX_DEPTH; depth += 1) {
    const stat = await realOf($, head)
    if (stat !== undefined) {
      if (stat.realPath === undefined) return undefined
      return [trimEnd(stat.realPath, sep), ...missing].join(sep)
    }
    const trimmed = trimEnd(head, sep)
    const cut = lastCut(trimmed, sep)
    if (cut < 0) return undefined
    const name = trimmed.slice(cut + 1)
    if (name === '' || /^[A-Za-z]:/.test(name)) return undefined
    if (name !== '.') missing.unshift(name)
    head = trimmed.slice(0, cut + 1)
  }
  return undefined
}

/**
 * The segments of `real` beneath `root` (both resolved), or undefined when it
 * is not beneath it. Whole segments only: `/proj-evil/x` is not under `/proj`.
 */
const segmentsUnder = (real: string, root: string, sep: string): string[] | undefined => {
  const base = trimEnd(root, sep)
  if (!real.startsWith(base + sep)) return undefined
  const segments = segmentsOf(real.slice(base.length + 1), sep)
  const isClean = segments.every(segment => segment !== '' && segment !== '.' && segment !== '..')
  return isClean ? segments : undefined
}

/** The allow-list of VOYAGE.md section 7, on whole path segments beneath the root. */
const isAllowed = (segments: readonly string[], phase: Phase): boolean => {
  // `.shipit/**`: the root's own `.shipit`, and something inside it.
  if (segments[0] === SHIPIT_DIR && segments.length > 1) return true
  if (!isPlanningPhase(phase)) return false

  const name = segments[segments.length - 1]
  // `CONTEXT.md` and `**/CONTEXT.md`.
  if (name === GLOSSARY) return true
  // `CONTEXT-MAP.md`, at the root only.
  if (name === CONTEXT_MAP && segments.length === 1) return true
  // `docs/adr/**` and `**/docs/adr/**`: a `docs` then `adr` pair above the file.
  return segments.some(
    (segment, at) => segment === ADR_PARENT && segments[at + 1] === ADR_DIR && at + 2 < segments.length,
  )
}

/** The path a guarded call writes: `notebook_path` for NotebookEdit, else `file_path`. */
const pathOf = (e: { tool: string; file_path?: unknown; notebook_path?: unknown }): unknown =>
  e.tool === 'NotebookEdit' ? e.notebook_path : e.file_path

/**
 * Why the main loop may not write `path` in `phase`, or undefined when it may.
 * Throws when the root cannot be resolved: the caller refuses on that too.
 */
const judge = async ($: EngineInterface, path: unknown, phase: Phase): Promise<string | undefined> => {
  if (typeof path !== 'string') throw new Error('shipit: the call names no path')

  const root = (await $.fs.stat(await $.session.root(), { resolve: true })).realPath
  if (root === undefined) throw new Error('shipit: the project root does not resolve')
  const sep = separatorOf(root)

  const real = await place($, path, sep)
  if (real === undefined) return refusal(path, phase, 'its location cannot be resolved')

  const segments = segmentsUnder(real, root, sep)
  if (segments === undefined) return refusal(path, phase, 'it is outside the project root')
  return isAllowed(segments, phase) ? undefined : refusal(path, phase, 'it is not on the allow-list')
}

const unjudged = (path: unknown): string =>
  `shipit: ${String(path)} was not written (the write guard could not judge it, so it was refused). ${remedy}`

export const registerGuard = (on: On, options: PluginOptions): void => {
  on('tool.call', { tool: ['Write', 'Edit', 'NotebookEdit'] }, async ($, e, next) => {
    // Decided before anything can throw: none of these is an armed guard.
    if (e.agentId !== undefined) return next(e)
    if (!isGuardEnabled(options)) return next(e)
    const { voyage, paused } = await readSnapshot($)
    if (paused || voyage === null || !isActivePhase(voyage.phase)) return next(e)

    // Armed from here on, and judged before `next`. A judgment that fails is
    // refused HERE, not left to `.catch`: register.tsx's observer hooks this
    // event too, with a handler that passes through, and of one plugin's
    // handlers on an event the first registered answers a throw (verified).
    const path = pathOf(e)
    const why = await judge($, path, voyage.phase).catch(() => unjudged(path))
    return why === undefined ? next(e) : { deny: why }
  }).catch(($, e, next) =>
    // Reached with the hook unjudged (it ran out of time, or the call rose
    // beneath one of its own `$` calls, where `$` rejects): decided from `e`
    // and `options` alone. What is never guarded passes; the rest is refused.
    next.called || e.agentId !== undefined || !isGuardEnabled(options) ? next(e) : { deny: unjudged(pathOf(e)) },
  )
}

files.hooks/pane.tsx:
// The voyage pane: the plan, its tasks, the F1-F4 verdicts and the evidence
// file names of the voyage this session owns, with a Pause / Resume button.
//
// Contract:
// - Open only on a user action, through the two seams, both filled
//   synchronously in `registerPane`:
//   `addSubcommand({ name: 'pane', summary, run: () => ({ text, open: { id: PANE_ID, title } }) })`
//   (Task 12's `/shipit` dispatcher calls `$.ui.open(answer.open)`) and
//   `addBandAction({ key: 'pane', label, open: { id: PANE_ID, title } })`
//   (Task 13's band draws the Button and opens on press). Never open from
//   `session.start`.
// - `ui.render` on `{ component: 'Pane', requestId: PANE_ID }`:
//   `await readSnapshot($)` and draw the header (plan, phase), each task with
//   its state and `waitingOn(task, progress)`, the F1-F4 `voyage.verdicts`,
//   and `snapshot.evidence` (the file names in `.shipit/evidence/`, listed by
//   register.tsx's refresh, never while drawing). No owned voyage: the empty
//   state naming `/shipit:go`.
// - Pause / Resume button: `onPress: () => togglePaused($)` below, the same
//   state `/shipit pause|resume` writes.
// - `$` stays in this file: `claude plugin validate` refuses a `$` handed to
//   an imported function, and a `$.state` reference that is not a const here.
// - From './state': snapshotOf, EMPTY, PANE_ID, addSubcommand, addBandAction,
//   hasStatusFormatter, statusText. From './voyage': waitingOn, VERDICT_KEYS
//   and the types.
// - Must NOT: write state while drawing, read or render file contents, call
//   `$.fs` from the render hook, or write `voyage` / `progress` / `evidence`.

import type { EngineInterface, On, PluginOptions } from 'claude-code'

import { EMPTY, PANE_ID, addBandAction, addSubcommand, hasStatusFormatter, snapshotOf, statusText } from './state'
import type { Snapshot } from './state'
import { VERDICT_KEYS, isGatePhase, waitingOn } from './voyage'
import type { Phase, TaskState, VerdictKey } from './voyage'

// --- provided by Task 10 (state.ts explains why this cannot be imported) ----

const VOYAGE = { plugin: 'shipit', key: 'voyage' } as const
const PROGRESS = { plugin: 'shipit', key: 'progress' } as const
const EVIDENCE = { plugin: 'shipit', key: 'evidence' } as const
const PAUSED = { plugin: 'shipit', key: 'paused' } as const
const NUDGES = { plugin: 'shipit', key: 'nudges' } as const

/**
 * The mod's state as it stands; never throws. Every `$.state.get` of one
 * dispatch reads one moment, so a value this dispatch wrote is not seen here.
 */
const readSnapshot = async ($: EngineInterface): Promise<Snapshot> => {
  try {
    return snapshotOf({
      voyage: (await $.state.get(VOYAGE)).value,
      progress: (await $.state.get(PROGRESS)).value,
      evidence: (await $.state.get(EVIDENCE)).value,
      paused: (await $.state.get(PAUSED)).value,
      nudges: (await $.state.get(NUDGES)).value,
    })
  } catch {
    return EMPTY
  }
}

/**
 * The Pause / Resume button's handler: flips the flag from the value held now
 * (never the one drawn), zeroes the nudge count on resume and brings the
 * status line up to date. A press that lost a race changes nothing.
 */
const togglePaused = async ($: EngineInterface): Promise<Snapshot> => {
  const before = await readSnapshot($)
  const held = await $.state.get(PAUSED)
  const paused = held.value !== true
  const { isSet } = await $.state.set(PAUSED, paused, { ifVersion: held.version })
  if (!isSet) return before
  if (!paused) await $.state.set(NUDGES, 0)
  const now: Snapshot = { ...before, paused, nudges: paused ? before.nudges : 0 }
  if (hasStatusFormatter()) $.ui.status(statusText(now))
  return now
}

// --- the view model (pure: no `$`) -------------------------------------------

export const PANE_TITLE = 'Voyage'
/** Evidence names drawn at most; the rest are counted in one closing line. */
export const MAX_EVIDENCE_ROWS = 200

const PHASE_LABELS: Record<Phase, string> = {
  planning: 'Planning',
  plan_gate: 'Plan gate',
  executing: 'Executing',
  reviewing: 'Reviewing',
  ship_gate: 'Ship gate',
  done: 'Done',
}

/** VOYAGE.md section 2: what each verdict key reviews. */
const DIMENSIONS: Record<VerdictKey, string> = {
  F1: 'Plan Compliance Audit',
  F2: 'Code Quality Review',
  F3: 'Real QA Execution',
  F4: 'Scope Fidelity Check',
}

export type TaskRow = {
  id: number
  title: string
  state: TaskState
  /** `waiting on 2, 5` for a blocked task; empty otherwise. */
  waiting: string
}

export type VerdictRow = {
  key: VerdictKey
  dimension: string
  verdict: 'APPROVE' | 'REJECT' | 'not run'
}

export type PaneView =
  | { kind: 'empty'; lines: string[] }
  | {
      kind: 'voyage'
      planName: string
      phase: string
      /** `paused`, `awaiting you`: what holds the voyage still. */
      markers: string[]
      /** `3/9 tasks done`, or that progress is unknown. */
      summary: string
      /** Null when progress is unknown (the plan cannot be read): no rows. */
      tasks: TaskRow[] | null
      verdicts: VerdictRow[]
      evidence: string[]
      /** Evidence names beyond the ones listed. */
      evidenceHidden: number
      isPaused: boolean
      buttonLabel: 'Pause' | 'Resume'
    }

/** What the pane shows for a snapshot. Pure: reads nothing but its argument. */
export const paneView = (snapshot: Snapshot): PaneView => {
  const { voyage, progress, evidence, paused } = snapshot
  if (voyage === null) {
    return {
      kind: 'empty',
      lines: [
        'No voyage in this session.',
        'This pane follows a shipit voyage: its plan, each task and what it waits on, the F1-F4 review verdicts and the evidence files.',
        'Run /shipit:go to start a voyage.',
      ],
    }
  }

  const markers = [
    ...(paused ? ['paused'] : []),
    ...(voyage.awaitingUser || isGatePhase(voyage.phase) ? ['awaiting you'] : []),
  ]
  return {
    kind: 'voyage',
    planName: voyage.planName,
    phase: PHASE_LABELS[voyage.phase],
    markers,
    summary:
      progress === null
        ? 'Progress unknown: the plan file could not be read.'
        : `${progress.done}/${progress.total} tasks done`,
    tasks:
      progress === null
        ? null
        : progress.tasks.map(task => {
            const waits = task.state === 'blocked' ? waitingOn(task, progress) : []
            return {
              id: task.id,
              title: task.title,
              state: task.state,
              waiting: waits.length === 0 ? '' : `waiting on ${waits.join(', ')}`,
            }
          }),
    verdicts: VERDICT_KEYS.map(key => ({
      key,
      dimension: DIMENSIONS[key],
      verdict: voyage.verdicts[key] ?? 'not run',
    })),
    evidence: evidence.slice(0, MAX_EVIDENCE_ROWS),
    evidenceHidden: Math.max(0, evidence.length - MAX_EVIDENCE_ROWS),
    isPaused: paused,
    buttonLabel: paused ? 'Resume' : 'Pause',
  }
}

// --- the pane ----------------------------------------------------------------

export const registerPane = (on: On, _options: PluginOptions): void => {
  // Opened only by something the person did: `/shipit pane` (enforcer.ts's
  // dispatcher opens what `run` answers) and the band's Button (band.tsx).
  addSubcommand({
    name: 'pane',
    summary: 'open the voyage pane (tasks, verdicts, evidence)',
    run: () => ({ text: 'Voyage pane opened.', open: { id: PANE_ID, title: PANE_TITLE } }),
  })
  addBandAction({ key: 'pane', label: 'Voyage', open: { id: PANE_ID, title: PANE_TITLE } })

  // The pane's body scrolls under the engine (`e.props.scroll`), so every task
  // is drawn, one row each (two when blocked), long text cut at the row's end.
  // The read subscribes the pane: a state write draws it again. Nothing here
  // writes; the one write is the button's press.
  on('ui.render', { component: 'Pane', requestId: 'shipit-voyage' }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const view = paneView(await readSnapshot($))

    if (view.kind === 'empty') {
      return (
        <Box key="empty" flexDirection="column" rowGap={1}>
          {view.lines.map((line, index) => (
            <Text bold={index === 0} dimColor={index === 1}>
              {line}
            </Text>
          ))}
        </Box>
      )
    }

    return (
      <Box key="voyage" flexDirection="column" rowGap={1}>
        <Box key="header" flexDirection="column">
          <Text bold wrap="truncate-end">
            {view.planName}
          </Text>
          <Text wrap="truncate-end">
            {[view.phase, ...view.markers].join(' · ')}
          </Text>
          <Text dimColor>{view.summary}</Text>
          <Box>
            <Button key="pause" hotkey="p" variant={view.isPaused ? 'primary' : 'secondary'} onPress={() => togglePaused($)}>
              {view.buttonLabel}
            </Button>
          </Box>
        </Box>

        <Box key="tasks" flexDirection="column">
          <Text bold>Tasks</Text>
          {view.tasks === null && <Text dimColor>Unknown: the plan file could not be read.</Text>}
          {view.tasks !== null && view.tasks.length === 0 && <Text dimColor>The plan has no tasks.</Text>}
          {(view.tasks ?? []).map(task => (
            <Box key={`task-${task.id}`} flexDirection="column">
              <Text dimColor={task.state === 'done'} bold={task.state === 'ready'} wrap="truncate-end">
                {`${task.state.padEnd(8)}${task.id}. ${task.title}`}
              </Text>
              {task.waiting !== '' && (
                <Text color="warning" wrap="truncate-end">
                  {`${' '.repeat(8)}${task.waiting}`}
                </Text>
              )}
            </Box>
          ))}
        </Box>

        <Box key="verdicts" flexDirection="column">
          <Text bold>Review verdicts</Text>
          {view.verdicts.map(row => (
            <Box key={`verdict-${row.key}`} flexDirection="row" columnGap={1}>
              <Text wrap="truncate-end">{`${row.key} ${row.dimension}:`}</Text>
              <Text
                color={row.verdict === 'APPROVE' ? 'success' : row.verdict === 'REJECT' ? 'error' : undefined}
                dimColor={row.verdict === 'not run'}
              >
                {row.verdict}
              </Text>
            </Box>
          ))}
        </Box>

        <Box key="evidence" flexDirection="column">
          <Text bold>{`Evidence (${view.evidence.length + view.evidenceHidden})`}</Text>
          {view.evidence.length === 0 && <Text dimColor>No evidence files yet.</Text>}
          {view.evidence.map(name => (
            <Text wrap="truncate-end">{name}</Text>
          ))}
          {view.evidenceHidden > 0 && <Text dimColor>{`and ${view.evidenceHidden} more`}</Text>}
        </Box>
      </Box>
    )
  })
}

