// What the shipit mod's files share: the snapshot's shape and rules, the
// userConfig readers, path helpers, and the seams guard.ts, enforcer.ts,
// band.tsx and pane.tsx meet at. Everything here is PURE: no `$`.
//
// Why no `$` here: `claude plugin validate` refuses a `$` handed to an
// imported function ("$ is followed only into a function declared in this
// same file") and a `$.state` reference that is not a const of the calling
// file. So every file that touches `$.state` declares the five references
// itself and keeps its own top-level `readSnapshot($)`:
//
//   const VOYAGE = { plugin: 'shipit', key: 'voyage' } as const
//   const PROGRESS = { plugin: 'shipit', key: 'progress' } as const
//   const EVIDENCE = { plugin: 'shipit', key: 'evidence' } as const
//   const PAUSED = { plugin: 'shipit', key: 'paused' } as const
//   const NUDGES = { plugin: 'shipit', key: 'nudges' } as const
//
//   const readSnapshot = async ($: EngineInterface): Promise<Snapshot> => {
//     try {
//       return snapshotOf({
//         voyage: (await $.state.get(VOYAGE)).value,
//         progress: (await $.state.get(PROGRESS)).value,
//         evidence: (await $.state.get(EVIDENCE)).value,
//         paused: (await $.state.get(PAUSED)).value,
//         nudges: (await $.state.get(NUDGES)).value,
//       })
//     } catch {
//       return EMPTY
//     }
//   }
//
// Who writes what: register.tsx's `refresh` is the ONLY writer of `voyage`,
// `progress` and `evidence` (it also clears `paused` / `nudges` when the
// voyage ends and zeroes `nudges` when progress moves). `paused` is written by
// `/shipit pause|resume` (enforcer.ts) and the pane's button (pane.tsx);
// `nudges` by enforcer.ts. Nobody writes while a `ui.render` hook draws, and
// nobody sets a key to `undefined`. The mod never writes `.shipit/`.

import type { CommandRunInput, CommandRunResult, PluginOptions } from 'claude-code'

import type { ShipitProgress, ShipitVoyage } from '../types'

export const SHIPIT_DIR = '.shipit'
export const VOYAGE_FILE = '.shipit/voyage.json'
export const EVIDENCE_DIR = '.shipit/evidence'
/** The `/shipit` command (spike: COMMAND_NAME). Task 12 registers it. */
export const COMMAND = 'shipit'
/** The voyage pane's `$.ui.open` id and its `ui.render` `requestId`. Task 14 opens it. */
export const PANE_ID = 'shipit-voyage'
/** The skills whose expansion refreshes the snapshot (spike: SKILL_EVENT_NAME). */
export const SKILLS = ['shipit:go', 'shipit:plan', 'shipit:execute', 'shipit:review'] as const
/** A plugin agent's type as `agent.spawn` carries it (verified: `<plugin>:<name>`). */
export const MAKER_AGENT = 'shipit:maker'
/** The enforcer stands down after this many nudges without progress. */
export const MAX_NUDGES = 3
const MAX_EVIDENCE = 500

// --- the snapshot ----------------------------------------------------------

/**
 * One reading of the mod's state. `voyage` is non-null ONLY for a valid record
 * this session owns, so "owned" is `snapshot.voyage !== null`; `progress` is
 * null without one, or when its plan cannot be read (unknown, not zero).
 */
export type Snapshot = {
  voyage: ShipitVoyage | null
  progress: ShipitProgress | null
  evidence: string[]
  paused: boolean
  nudges: number
}

/** The five `$.state` values as read: each undefined until first written. */
export type RawSnapshot = {
  voyage?: ShipitVoyage | null | undefined
  progress?: ShipitProgress | null | undefined
  evidence?: string[] | undefined
  paused?: boolean | undefined
  nudges?: number | undefined
}

export const EMPTY: Snapshot = { voyage: null, progress: null, evidence: [], paused: false, nudges: 0 }

/** The snapshot the values read from `$.state` come to, defaults filled in. */
export const snapshotOf = (raw: RawSnapshot): Snapshot => ({
  voyage: raw.voyage ?? null,
  progress: raw.progress ?? null,
  evidence: Array.isArray(raw.evidence) ? raw.evidence : [],
  paused: raw.paused === true,
  nudges: typeof raw.nudges === 'number' && raw.nudges > 0 ? Math.trunc(raw.nudges) : 0,
})

/** What the files on disk say; `voyage` already checked for validity and ownership. */
export type Disk = Pick<Snapshot, 'voyage' | 'progress' | 'evidence'>

export const NO_VOYAGE: Disk = { voyage: null, progress: null, evidence: [] }

/** The evidence file names of a `$.fs.list` answer: files only, sorted, capped. */
export const evidenceNames = (entries: readonly { name: string; kind: string }[]): string[] =>
  entries
    .filter(entry => entry.kind === 'file')
    .map(entry => entry.name)
    .sort()
    .slice(0, MAX_EVIDENCE)

const progressMark = (snapshot: Disk): string =>
  JSON.stringify([snapshot.voyage?.phase, snapshot.progress?.done, snapshot.voyage?.verdicts])

/**
 * The snapshot a refresh settles on. Without an owned voyage the pause flag
 * and nudge count are cleared (a pause ends with its voyage); with one, the
 * nudge count goes back to zero whenever the phase, the done count or a
 * verdict moved since `before`.
 */
export const settle = (before: Snapshot, disk: Disk): Snapshot => {
  if (disk.voyage === null) return { ...EMPTY }
  const hasMoved = progressMark(disk) !== progressMark(before)
  return { ...disk, paused: before.paused, nudges: hasMoved ? 0 : before.nudges }
}

/** The keys whose value differs between two snapshots, in the order a refresh writes them. */
export const changedKeys = (before: Snapshot, now: Snapshot): (keyof Snapshot)[] =>
  (['progress', 'evidence', 'paused', 'nudges', 'voyage'] as const).filter(
    key => JSON.stringify(before[key]) !== JSON.stringify(now[key]),
  )

// --- userConfig ------------------------------------------------------------

/** The `guard` option: on unless set to false. */
export const isGuardEnabled = (options: PluginOptions): boolean => options.guard !== false

/** The `enforcer` option: on unless set to false. */
export const isEnforcerEnabled = (options: PluginOptions): boolean => options.enforcer !== false

/** The `maker_model` option, or undefined when unset or blank. */
export const makerModelOf = (options: PluginOptions): string | undefined => {
  const model = options.maker_model
  return typeof model === 'string' && model.trim() !== '' ? model.trim() : undefined
}

// --- paths -----------------------------------------------------------------

const isAbsolute = (path: string): boolean => /^([\\/]|[A-Za-z]:[\\/])/.test(path)

/** `rel` under `root` (as given when already absolute), joined with the root's own separator. */
export const pathUnder = (root: string, rel: string): string => {
  if (isAbsolute(rel)) return rel
  const sep = root.includes('/') || !root.includes('\\') ? '/' : '\\'
  return `${root.replace(/[\\/]+$/, '')}${sep}${rel}`
}

/** True when a tool's path argument has a `.shipit` segment: the observer's cue to refresh. Not a gate. */
export const isShipitPath = (path: unknown): boolean =>
  typeof path === 'string' && path.split(/[\\/]/).includes(SHIPIT_DIR)

// --- seams -----------------------------------------------------------------
// Registries the four feature files fill synchronously inside their own
// `registerX(on, options)`. No entry ever receives `$` from another file: a
// subcommand answers with data, and the file that holds `$` acts on it.

/** The status line text for a snapshot; undefined clears the entry. Task 13 supplies it. */
export type StatusFormatter = (snapshot: Snapshot) => string | undefined

/** What a contributed `/shipit <name>` subcommand asks the dispatcher to do. */
export type SubcommandAnswer = CommandRunResult & {
  /** Open this pane with `$.ui.open({ id, title })` before answering. */
  open?: { id: string; title: string }
}

/** A `/shipit <name> ...` subcommand another file contributes to Task 12's dispatcher. */
export type Subcommand = {
  /** The first word after `/shipit`, lower case. */
  name: string
  /** One line for the usage listing. */
  summary: string
  /** Pure: `args` is what followed the name, trimmed; `snapshot` is current. */
  run: (args: string, snapshot: Snapshot, e: CommandRunInput) => SubcommandAnswer
}

/** A Button another file contributes to the band: pressing it opens a pane. */
export type BandAction = {
  /** The Button's `key`, unique on the band. */
  key: string
  label: string
  /** The band's `onPress` calls `$.ui.open(action.open)`. */
  open: { id: string; title: string }
}

let statusFormatter: StatusFormatter | undefined
const subcommands = new Map<string, Subcommand>()
const bandActions = new Map<string, BandAction>()

/** Empties the registries. register.tsx calls it first, so a reload starts clean. */
export const resetSeams = (): void => {
  statusFormatter = undefined
  subcommands.clear()
  bandActions.clear()
}

/**
 * Task 13: supplies the status line's text. Once set, register.tsx calls
 * `$.ui.status(statusText(snapshot))` after every refresh; a file that changes
 * `paused` itself does the same after its write.
 */
export const setStatusFormatter = (formatter: StatusFormatter): void => {
  statusFormatter = formatter
}

export const hasStatusFormatter = (): boolean => statusFormatter !== undefined

/** The status line text for `snapshot`: undefined with no formatter or when it says to clear. */
export const statusText = (snapshot: Snapshot): string | undefined => {
  try {
    return statusFormatter?.(snapshot)
  } catch {
    return undefined
  }
}

/** Contributes a `/shipit` subcommand; the same name again replaces it. */
export const addSubcommand = (subcommand: Subcommand): void => {
  subcommands.set(subcommand.name.toLowerCase(), subcommand)
}

export const findSubcommand = (name: string): Subcommand | undefined => subcommands.get(name.toLowerCase())

export const listSubcommands = (): Subcommand[] => [...subcommands.values()]

/** Contributes a band Button; the same key again replaces it. */
export const addBandAction = (action: BandAction): void => {
  bandActions.set(action.key, action)
}

export const listBandActions = (): BandAction[] => [...bandActions.values()]

