// The voyage contract (skills/VOYAGE.md sections 2, 3 and 5) as pure functions:
// no `$`, no I/O, and nothing here throws on bad input.

import type {
  ShipitPhase,
  ShipitProgress,
  ShipitTask,
  ShipitVerdict,
  ShipitVerdictKey,
  ShipitVerdicts,
  ShipitVoyage,
} from '../types'

export type Phase = ShipitPhase
export type Verdict = ShipitVerdict
export type VerdictKey = ShipitVerdictKey
export type Verdicts = ShipitVerdicts
export type Voyage = ShipitVoyage
export type Task = ShipitTask
export type TaskState = ShipitTask['state']
export type Progress = ShipitProgress

export const PHASES = ['planning', 'plan_gate', 'executing', 'reviewing', 'ship_gate', 'done'] as const
export const VERDICT_KEYS = ['F1', 'F2', 'F3', 'F4'] as const

const TASK_LINE = /^- \[( |x|X)\] (\d+)\. (.*)$/
const DEPENDS_ON = /^\s*(?:[-*]\s+)?\*\*Depends on\*\*:\s*(.*)$/
const BLOCKED_BY = /^\s*(?:[-*]\s+)?\*\*Blocked By\*\*:\s*(.*)$/

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const isFilled = (value: unknown): value is string => typeof value === 'string' && value !== ''

export const isPhase = (value: unknown): value is Phase =>
  typeof value === 'string' && (PHASES as readonly string[]).includes(value)

/** Guard phases: every phase except `done`. */
export const isActivePhase = (phase: Phase): boolean => phase !== 'done'

/** Enforcer phases: `executing` and `reviewing`. */
export const isEnforcerPhase = (phase: Phase): boolean => phase === 'executing' || phase === 'reviewing'

/** The phases whose allow-list includes the glossary and ADR paths. */
export const isPlanningPhase = (phase: Phase): boolean => phase === 'planning' || phase === 'plan_gate'

/** `plan_gate` and `ship_gate`: waiting for the user whatever `awaitingUser` says. */
export const isGatePhase = (phase: Phase): boolean => phase === 'plan_gate' || phase === 'ship_gate'

/** The plan file's basename without `.md`. */
export const planNameOf = (activePlan: string): string =>
  (activePlan.split(/[\\/]/).pop() ?? activePlan).replace(/\.md$/, '')

const verdictOf = (value: unknown): Verdict => (value === 'APPROVE' || value === 'REJECT' ? value : null)

/**
 * The record in `text` (the content of `.shipit/voyage.json`), normalised, or
 * undefined when it is not a voyage: not a string, unparseable, not an object,
 * an unknown `phase`, or no `active_plan` / `session_id` (the legacy shape).
 */
export const parseVoyage = (text: unknown): Voyage | undefined => {
  if (typeof text !== 'string') return undefined
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    return undefined
  }
  if (!isRecord(raw)) return undefined
  const { phase, active_plan: activePlan, session_id: sessionId } = raw
  if (!isPhase(phase) || !isFilled(activePlan) || !isFilled(sessionId)) return undefined

  const verdicts = isRecord(raw.verdicts) ? raw.verdicts : {}
  return {
    planName: isFilled(raw.plan_name) ? raw.plan_name : planNameOf(activePlan),
    activePlan,
    startedAt: isFilled(raw.started_at) ? raw.started_at : null,
    sessionId,
    phase,
    awaitingUser: raw.awaiting_user === true,
    verdicts: {
      F1: verdictOf(verdicts.F1),
      F2: verdictOf(verdicts.F2),
      F3: verdictOf(verdicts.F3),
      F4: verdictOf(verdicts.F4),
    },
  }
}

/** True when `voyage` is a valid record whose `sessionId` is this session's. */
export const isOwned = (voyage: Voyage | null | undefined, sessionId: unknown): voyage is Voyage =>
  voyage !== null && voyage !== undefined && isFilled(sessionId) && voyage.sessionId === sessionId

/** The lines of the `## TODOs` section, or every line when the plan has no such heading. */
const todoLines = (planText: string): string[] => {
  const lines = planText.split(/\r?\n/)
  const start = lines.findIndex(line => line.trimEnd() === '## TODOs')
  if (start < 0) return lines
  const rest = lines.slice(start + 1)
  const end = rest.findIndex(line => line.startsWith('## '))
  return end < 0 ? rest : rest.slice(0, end)
}

/** The ids a dependency value names: cut at the first `(`, then every integer. */
export const parseDependencyIds = (value: string): number[] => {
  const cut = value.indexOf('(')
  const ids = ((cut < 0 ? value : value.slice(0, cut)).match(/\d+/g) ?? []).map(Number)
  return [...new Set(ids)]
}

const dependenciesOf = (block: readonly string[]): number[] => {
  for (const pattern of [DEPENDS_ON, BLOCKED_BY]) {
    for (const line of block) {
      const value = pattern.exec(line)?.[1]
      if (value !== undefined) return parseDependencyIds(value)
    }
  }
  return []
}

/**
 * Progress read from a plan's text (VOYAGE.md section 3), or undefined when
 * `planText` is not a string. A dangling dependency id or a cycle leaves the
 * tasks concerned `blocked`; neither fails the read.
 */
export const parseProgress = (planText: unknown): Progress | undefined => {
  if (typeof planText !== 'string') return undefined

  const found: { id: number; title: string; checked: boolean; block: string[] }[] = []
  for (const line of todoLines(planText)) {
    const hit = TASK_LINE.exec(line)
    if (hit !== null) {
      found.push({ id: Number(hit[2]), title: (hit[3] ?? '').trim(), checked: hit[1] !== ' ', block: [] })
    } else {
      found.at(-1)?.block.push(line)
    }
  }

  const doneIds = new Set(found.filter(task => task.checked).map(task => task.id))
  const tasks = found.map(({ id, title, checked, block }): Task => {
    const dependsOn = dependenciesOf(block)
    const isReady = dependsOn.every(dep => dep !== id && doneIds.has(dep))
    return { id, title, checked, dependsOn, state: checked ? 'done' : isReady ? 'ready' : 'blocked' }
  })

  return { done: tasks.filter(task => task.checked).length, total: tasks.length, tasks }
}

/** The unchecked tasks whose dependencies are all done, in plan order. */
export const readyTasks = (progress: Progress | null | undefined): Task[] =>
  (progress?.tasks ?? []).filter(task => task.state === 'ready')

/** The task to name in a nudge: the first ready one, else the first unchecked one. */
export const nextTask = (progress: Progress | null | undefined): Task | undefined =>
  readyTasks(progress)[0] ?? (progress?.tasks ?? []).find(task => !task.checked)

/** The dependency ids `task` still waits on: not done, or naming no task. */
export const waitingOn = (task: Task, progress: Progress | null | undefined): number[] => {
  const doneIds = new Set((progress?.tasks ?? []).filter(one => one.checked).map(one => one.id))
  return task.checked ? [] : task.dependsOn.filter(dep => dep === task.id || !doneIds.has(dep))
}

/** The verdict keys that are not `APPROVE` (null or `REJECT`). */
export const pendingVerdicts = (verdicts: Verdicts): VerdictKey[] =>
  VERDICT_KEYS.filter(key => verdicts[key] !== 'APPROVE')

/**
 * VOYAGE.md section 8's "work remains": in `executing` a task that is not
 * done, in `reviewing` a verdict that is not `APPROVE`; false in every other
 * phase, and false in `executing` while progress is unknown (an unreadable
 * plan is not known to have work left).
 */
export const workRemains = (voyage: Voyage | null | undefined, progress: Progress | null | undefined): boolean => {
  if (voyage === null || voyage === undefined) return false
  if (voyage.phase === 'executing') return progress !== null && progress !== undefined && progress.done < progress.total
  if (voyage.phase === 'reviewing') return pendingVerdicts(voyage.verdicts).length > 0
  return false
}

