{
  "name": "shipit",
  "description": "Plan it, execute it, ship it. One /shipit:go runs the whole voyage in a single session.",
  "version": "2.0.1",
  "author": {
    "name": "Darin Haener"
  },
  "dependencies": [
    "mattpocock-skills@claude-plugins-official"
  ],
  "types": "./types/index.d.ts",
  "userConfig": {
    "maker_model": {
      "type": "string",
      "title": "Maker model",
      "description": "Model alias or id for shipit:maker subagents. Leave empty to inherit the session's model."
    },
    "enforcer": {
      "type": "boolean",
      "title": "Continuation enforcer",
      "description": "Nudge the main loop to keep going while an owned voyage is executing or reviewing and work remains.",
      "default": true
    },
    "guard": {
      "type": "boolean",
      "title": "Write guard",
      "description": "Keep the main loop from writing outside .shipit/ (and the planning glossary/ADR files) while it owns an active voyage.",
      "default": true
    }
  }
}

files.types/index.d.ts:
/** The six voyage phases of VOYAGE.md section 2. */
export type ShipitPhase = 'planning' | 'plan_gate' | 'executing' | 'reviewing' | 'ship_gate' | 'done'

/** One review verdict; null is "not run yet, or invalidated and due again". */
export type ShipitVerdict = 'APPROVE' | 'REJECT' | null

export type ShipitVerdictKey = 'F1' | 'F2' | 'F3' | 'F4'

export type ShipitVerdicts = Record<ShipitVerdictKey, ShipitVerdict>

/** A valid `.shipit/voyage.json`, normalised: camelCase, optional fields defaulted. */
export type ShipitVoyage = {
  planName: string
  /** As stored: relative to the project root. */
  activePlan: string
  /** Display only; null when the record carries none. */
  startedAt: string | null
  sessionId: string
  phase: ShipitPhase
  awaitingUser: boolean
  verdicts: ShipitVerdicts
}

export type ShipitTaskState = 'done' | 'ready' | 'blocked'

export type ShipitTask = {
  id: number
  title: string
  checked: boolean
  dependsOn: number[]
  state: ShipitTaskState
}

/** Task progress derived from the plan's `## TODOs` checkboxes. */
export type ShipitProgress = { done: number; total: number; tasks: ShipitTask[] }

declare module 'claude-code' {
  interface PluginState {
    shipit: {
      /** The voyage this session owns; null when there is none (missing, corrupt, legacy or foreign). */
      voyage: ShipitVoyage | null
      /** Progress of the owned voyage's plan; null when there is no owned voyage or the plan cannot be read. */
      progress: ShipitProgress | null
      /** File names in `.shipit/evidence/`, sorted; empty without an owned voyage. */
      evidence: string[]
      /** `/shipit pause`: suspends guard and enforcer for this session. */
      paused: boolean
      /** Consecutive enforcer nudges without progress. */
      nudges: number
    }
  }
}
